class Solution {
    struct Fenwick {
        int n;
        vector<int> tree;
        Fenwick(int n) : n(n), tree(n + 1, 0) {}
        void add(int idx, int val) {
            for (++idx; idx <= n; idx += idx & -idx) tree[idx] += val;
        }
        int query(int idx) {
            int sum = 0;
            for (++idx; idx > 0; idx -= idx & -idx) sum += tree[idx];
            return sum;
        }
        int range_query(int l, int r) {
            if (l > r) return 0;
            return query(r) - query(l - 1);
        }
    };
public:
    vector<int> countOfPeaks(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        Fenwick bit(n);
        auto is_peak = [&](int i) {
            return (i > 0 && i < n - 1 && nums[i] > nums[i - 1] && nums[i] > nums[i + 1]) ? 1 : 0;
        };
        vector<int> peak_status(n, 0);
        for (int i = 0; i < n; ++i) {
            peak_status[i] = is_peak(i);
            if (peak_status[i]) bit.add(i, 1);
        }
        vector<int> ans;
        for (const auto& q : queries) {
            if (q[0] == 1) {
                ans.push_back(bit.range_query(q[1] + 1, q[2] - 1));
            } else {
                int idx = q[1], val = q[2];
                nums[idx] = val;
                for (int i = idx - 1; i <= idx + 1; ++i) {
                    if (i >= 0 && i < n) {
                        int ns = is_peak(i);
                        if (ns != peak_status[i]) {
                            bit.add(i, ns - peak_status[i]);
                            peak_status[i] = ns;
                        }
                    }
                }
            }
        }
        return ans;
    }
};

